
"use client";

import { useState } from "react";
import {
  Users,
  Target,
  TrendingUp,
  MapPin,
  RefreshCw,
  Lock,
  UserPlus
} from "lucide-react";

export default function Dashboard() {
  const [showAddStudent, setShowAddStudent] = useState(false);

  const initialStudent = {
    studentName: "",
    email: "",
    phone: "",
    city: "",
    stream: "Science",
    interests: "",
    experience: "Beginner",
    favoriteSubject: "",
    careerGoal: "",
    language: "English",
    guardianConsent: false,
    consent: false
  };

  const [student, setStudent] = useState(initialStudent);
  const [saving, setSaving] = useState(false);
  const [studentMessage, setStudentMessage] = useState("");

  const [key, setKey] = useState("");
  const [data, setData] = useState<any>(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  // Load dashboard analytics
  async function loadDashboard() {
    setLoading(true);
    setError("");

    try {
      const response = await fetch("/api/analytics", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-admin-key": key
        },
        body: JSON.stringify({})
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.error || "Unable to load dashboard");
      }

      setData(result);
    } catch (e: unknown) {
      setError(
        e instanceof Error
          ? e.message
          : "Unable to load dashboard"
      );
    } finally {
      setLoading(false);
    }
  }

  // Add new student
  async function addStudent() {
    setSaving(true);
    setStudentMessage("");

    try {
      if (!student.consent) {
        throw new Error("Student consent is required.");
      }

      const response = await fetch("/api/admin/add-student", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-admin-key": key
        },
        body: JSON.stringify({
          ...student,
          interests: student.interests
            .split(",")
            .map((x) => x.trim())
            .filter(Boolean)
        })
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.error || "Unable to add student");
      }

      setStudentMessage("Student added successfully!");
      setShowAddStudent(false);
      setStudent(initialStudent);

      await loadDashboard();

    } catch (e: unknown) {
      setStudentMessage(
        e instanceof Error
          ? e.message
          : "Unable to add student."
      );
    } finally {
      setSaving(false);
    }
  }

  // Admin login screen
  if (!data) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-[#080d1b] p-6 text-white">
        <div className="w-full max-w-md rounded-2xl border border-slate-700 bg-slate-900 p-8">

          <Lock className="mb-5 text-cyan-400" size={32} />

          <h1 className="text-2xl font-bold">
            Growth Dashboard
          </h1>

          <p className="my-4 text-sm text-slate-400">
            Enter your administrator access key.
          </p>

          <input
            type="password"
            value={key}
            onChange={(e) => setKey(e.target.value)}
            placeholder="Admin key"
            className="w-full rounded-xl border border-slate-700 bg-slate-950 p-4"
          />

          {error && (
            <p className="mt-3 text-sm text-red-400">
              {error}
            </p>
          )}

          <button
            onClick={loadDashboard}
            disabled={!key || loading}
            className="mt-4 w-full rounded-xl bg-cyan-500 p-4 font-bold text-slate-950 disabled:opacity-50"
          >
            {loading ? "Loading..." : "Access dashboard"}
          </button>

        </div>
      </main>
    );
  }

  const metrics = data.metrics;

  return (
    <main className="min-h-screen bg-[#080d1b] p-6 text-white md:p-10">

      <div className="mx-auto max-w-7xl">

        {/* Header */}

        <div className="mb-8 flex flex-wrap items-center justify-between gap-4">

          <div>
            <p className="text-sm text-cyan-400">
              PATHFINDER AI
            </p>

            <h1 className="mt-2 text-3xl font-bold">
              Growth Intelligence
            </h1>

            <p className="mt-2 text-slate-400">
              Student acquisition and lead qualification
            </p>
          </div>

          <button
            onClick={loadDashboard}
            disabled={loading}
            className="flex items-center gap-2 rounded-xl border border-slate-700 p-3 disabled:opacity-50"
          >
            <RefreshCw size={16} />
            {loading ? "Refreshing..." : "Refresh"}
          </button>

        </div>

        {/* Add Student Button */}

        <div className="mb-6 flex flex-wrap gap-3">

          <button
            onClick={() => {
              setShowAddStudent(!showAddStudent);
              setStudentMessage("");
            }}
            className="flex items-center gap-2 rounded-xl bg-cyan-500 px-5 py-3 font-bold text-slate-950"
          >
            <UserPlus size={18} />
            {showAddStudent ? "Close Form" : "Add Student"}
          </button>

        </div>

        {/* Add Student Form */}

        {showAddStudent && (

          <div className="mb-8 rounded-2xl border border-slate-700 bg-slate-900 p-6">

            <h2 className="mb-5 text-xl font-bold">
              Add New Student
            </h2>

            <div className="grid gap-4 md:grid-cols-2">

              {[
                ["studentName", "Student Name"],
                ["email", "Email Address"],
                ["phone", "Phone Number"],
                ["city", "City"],
                ["favoriteSubject", "Favorite Subject"],
                ["careerGoal", "Career Goal"]
              ].map(([field, label]) => (

                <input
                  key={field}
                  placeholder={label}
                  value={student[field as keyof typeof student] as string}
                  onChange={(e) =>
                    setStudent({
                      ...student,
                      [field]: e.target.value
                    })
                  }
                  className="rounded-xl border border-slate-700 bg-slate-950 p-4"
                />

              ))}

              <select
                value={student.stream}
                onChange={(e) =>
                  setStudent({
                    ...student,
                    stream: e.target.value
                  })
                }
                className="rounded-xl border border-slate-700 bg-slate-950 p-4"
              >
                <option>Science</option>
                <option>Commerce</option>
                <option>Arts</option>
                <option>Other</option>
              </select>

              <select
                value={student.experience}
                onChange={(e) =>
                  setStudent({
                    ...student,
                    experience: e.target.value
                  })
                }
                className="rounded-xl border border-slate-700 bg-slate-950 p-4"
              >
                <option>Beginner</option>
                <option>Intermediate</option>
                <option>Advanced</option>
              </select>

              <input
                placeholder="Interests (comma separated)"
                value={student.interests}
                onChange={(e) =>
                  setStudent({
                    ...student,
                    interests: e.target.value
                  })
                }
                className="rounded-xl border border-slate-700 bg-slate-950 p-4"
              />

              <select
                value={student.language}
                onChange={(e) =>
                  setStudent({
                    ...student,
                    language: e.target.value
                  })
                }
                className="rounded-xl border border-slate-700 bg-slate-950 p-4"
              >
                {[
                  "English",
                  "Telugu",
                  "Hindi",
                  "Tamil",
                  "Kannada",
                  "Malayalam"
                ].map((language) => (
                  <option key={language}>
                    {language}
                  </option>
                ))}
              </select>

            </div>

            {/* Guardian Consent */}

            <label className="mt-5 flex items-center gap-3 text-sm">

              <input
                type="checkbox"
                checked={student.guardianConsent}
                onChange={(e) =>
                  setStudent({
                    ...student,
                    guardianConsent: e.target.checked
                  })
                }
              />

              Guardian consent obtained (where applicable)

            </label>

            {/* Student Consent */}

            <label className="mt-4 flex items-center gap-3 text-sm">

              <input
                type="checkbox"
                checked={student.consent}
                onChange={(e) =>
                  setStudent({
                    ...student,
                    consent: e.target.checked
                  })
                }
              />

              Student has provided consent for data collection.

            </label>

            {/* Form Buttons */}

            <div className="mt-6 flex flex-wrap gap-3">

              <button
                onClick={addStudent}
                disabled={saving || !student.consent}
                className="rounded-xl bg-cyan-500 px-6 py-3 font-bold text-slate-950 disabled:opacity-50"
              >
                {saving ? "Saving..." : "Save Student"}
              </button>

              <button
                onClick={() => {
                  setShowAddStudent(false);
                  setStudentMessage("");
                }}
                disabled={saving}
                className="rounded-xl border border-slate-700 px-6 py-3"
              >
                Cancel
              </button>

            </div>

            {studentMessage && (
              <p className="mt-4 text-sm text-cyan-400">
                {studentMessage}
              </p>
            )}

          </div>

        )}

        {/* Analytics Cards */}

        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">

          {[
            {
              title: "Total leads",
              value: metrics.total,
              icon: Users
            },
            {
              title: "High-intent leads",
              value: metrics.highIntent,
              icon: Target
            },
            {
              title: "High-intent rate",
              value: `${metrics.highIntentRate}%`,
              icon: TrendingUp
            },
            {
              title: "Medium-intent leads",
              value: metrics.mediumIntent,
              icon: MapPin
            }
          ].map((item) => (

            <div
              key={item.title}
              className="rounded-2xl border border-slate-700 bg-slate-900 p-6"
            >
              <item.icon className="mb-5 text-cyan-400" />

              <p className="text-sm text-slate-400">
                {item.title}
              </p>

              <p className="mt-2 text-3xl font-bold">
                {item.value}
              </p>

            </div>

          ))}

        </div>

        {/* Interests and Cities */}

        <div className="mt-8 grid gap-6 lg:grid-cols-2">

          <div className="rounded-2xl border border-slate-700 bg-slate-900 p-6">

            <h2 className="mb-5 text-xl font-bold">
              Popular interests
            </h2>

            {Object.entries(metrics.interests || {}).map(
              ([name, count]: any) => (

                <div key={name} className="mb-4">

                  <div className="mb-2 flex justify-between text-sm">
                    <span>{name}</span>
                    <span className="text-cyan-400">
                      {count}
                    </span>
                  </div>

                  <div className="h-2 rounded-full bg-slate-800">
                    <div
                      className="h-2 rounded-full bg-cyan-400"
                      style={{
                        width: `${
                          Math.min(
                            100,
                            Number(count) /
                              Math.max(1, metrics.total) *
                              100
                          )
                        }%`
                      }}
                    />
                  </div>

                </div>

              )
            )}

          </div>

          <div className="rounded-2xl border border-slate-700 bg-slate-900 p-6">

            <h2 className="mb-5 text-xl font-bold">
              Leads by city
            </h2>

            {Object.entries(metrics.cities || {}).map(
              ([name, count]: any) => (

                <div
                  key={name}
                  className="mb-4 flex justify-between border-b border-slate-800 pb-3"
                >
                  <span>{name}</span>
                  <span className="text-cyan-400">
                    {count}
                  </span>
                </div>

              )
            )}

          </div>

        </div>

        {/* Recent Leads Table */}

        <div className="mt-8 overflow-x-auto rounded-2xl border border-slate-700 bg-slate-900 p-6">

          <h2 className="mb-5 text-xl font-bold">
            Recent leads
          </h2>

          <table className="w-full text-left text-sm">

            <thead className="text-slate-400">
              <tr>
                <th className="p-3">Student</th>
                <th className="p-3">City</th>
                <th className="p-3">Interests</th>
                <th className="p-3">Score</th>
                <th className="p-3">Category</th>
              </tr>
            </thead>

            <tbody>

              {(data.leads || []).map((lead: any) => (

                <tr
                  key={lead.id}
                  className="border-t border-slate-800"
                >
                  <td className="p-3">
                    {lead.student_name}
                  </td>

                  <td className="p-3">
                    {lead.city}
                  </td>

                  <td className="p-3">
                    {(lead.interests || []).join(", ")}
                  </td>

                  <td className="p-3">
                    {lead.lead_score}
                  </td>

                  <td className="p-3">
                    {lead.lead_category}
                  </td>
                </tr>

              ))}

            </tbody>

          </table>

        </div>

      </div>

    </main>
  );
}
